INSERT INTO knowledge.war_outpost_rules (id,name,outpost_victory_points,exact_visible_effect,exact_visible_phase_rule,source_id,review_state) VALUES
  ('ravenous-pack','Ravenous Pack',15000,'Every 3 turns enemies become WOUNDED for 3 turns.','Bonuses apply to both teams in Phase 3 and the winning Alliance in Phase 4.',102131,'screenshot_verified_current'),
  ('crimson-bastion','Crimson Bastion',15000,'All Red team members gain +25% DEF.','Bonuses apply to both teams in Phase 3 and the winning Alliance in Phase 4.',102133,'screenshot_verified_current'),
  ('harpys-pit','Harpy''s Pit',10000,'All enemies begin battle WOUNDED for 3 turns.','Bonuses apply to both teams in Phase 3 and the winning Alliance in Phase 4.',102134,'screenshot_verified_current'),
  ('ashen-waste','Ashen Waste',10000,'All enemies begin battle afflicted with 2 FIRE.','Bonuses apply to both teams in Phase 3 and the winning Alliance in Phase 4.',102135,'screenshot_verified_current'),
  ('scouts-post','Scout''s Post',10000,'All enemies begin battle SCOUTED for 2 turns.','Bonuses apply to both teams in Phase 3 and the winning Alliance in Phase 4.',102139,'screenshot_verified_current')
INSERT INTO knowledge.legendary_assault_tips (id,encounter_name,exact_visible_text,review_state) VALUES
  ('viserion-pacified','Viserion','Don''t hit Viserion while he''s PACIFIED or he''ll get angry!','screenshot_verified_current'),
  ('viserion-brittle','Viserion','If Viserion is BRITTLE, you can strike him even when he''s asleep with no consequences.','screenshot_verified_current'),
  ('viserion-raid','Viserion','Each stack of RAID applied to Viserion will significantly weaken his defences.','screenshot_verified_current'),
  ('drogon-fast-champions','Drogon','Use fast champions to prevent Drogon''s Brimstone Rain ability.','screenshot_verified_current'),
  ('drogon-birthright','Drogon','Champions with BIRTHRIGHT are strong against Drogon.','screenshot_verified_current'),
  ('drogon-shields-fire','Drogon','Be careful, Drogon can destroy shields and is immune to FIRE.','screenshot_verified_current'),
  ('rhaegal-bleed','Rhaegal','Rhaegal uses his Skill every turn, BLEED will deal substantial damage!','screenshot_verified_current'),
  ('rhaegal-fire','Rhaegal','FIRE will deal bonus damage, stay alive while FIRE burns!','screenshot_verified_current'),
  ('rhaegal-taunt','Rhaegal','Focus on keeping your TAUNTING ally alive.','screenshot_verified_current')
