INSERT INTO knowledge.faction_rules (id,faction_id,exact_text,live_status,source_id,announced_update_id) VALUES
  ('free-cities-bonus','sqlite-faction-4672656520436974696573','All team members gain +25% Gem Damage and Skill stamina cost reduced 35%.','live',102557,NULL),
  ('lannister-bonus','sqlite-faction-4c616e6e6973746572','All team members gain +25% Gem Damage and +30% DEF.','live',102558,NULL),
  ('baratheon-bonus','sqlite-faction-426172617468656f6e','All team members gain +25% Gem Damage and +30% ATK.','live',102559,NULL),
  ('blacks-bonus','audit-faction-blacks','All team members gain +25% Gem Damage and +30% DEF.','live',102560,NULL),
  ('brotherhood-bonus','audit-faction-brotherhood','All team members gain +25% Gem Damage and +30% Critical Strike Chance.','live',102563,NULL),
  ('free-folk-bonus','sqlite-faction-4672656520466f6c6b','All team members gain +25% Gem Damage and +30% Critical Strike Chance.','live',102565,NULL),
  ('greens-bonus','sqlite-faction-477265656e73','All team members gain +25% Gem Damage and +25% Power.','live',102566,NULL),
  ('greyjoy-bonus','audit-faction-greyjoy','All team members gain +25% Gem Damage and Skill stamina cost reduced 25%.','live',102567,NULL),
  ('nights-watch-bonus','sqlite-faction-4e696768742773205761746368','All team members gain +25% Gem Damage and +25% ATK.','live',102569,NULL),
  ('stark-bonus','sqlite-faction-537461726b','All team members gain +25% Gem Damage and +30% DEF.','live',102570,NULL),
  ('targaryen-bonus','sqlite-faction-54617267617279656e','All team members gain +25% Gem Damage and +25% Durability.','live',102571,NULL),
  ('bolton-bonus','audit-faction-bolton','All team members gain +25% Gem Damage and +30% DEF.','live',102776,NULL),
  ('targaryen-how-to-play','sqlite-faction-54617267617279656e','Targaryens aim to win with FIRE. Their power begins low, but as they afflict more FIRE, their might grows.','live',102580,NULL),
  ('stark-how-to-play','sqlite-faction-537461726b','Starks win with ICE. They build up ICE on enemies until they become BRITTLE, then exploit that advantage.','live',102772,NULL),
  ('baratheon-how-to-play','sqlite-faction-426172617468656f6e','Baratheons rely on the game board to win. Increased Gem Damage and game board effects reward match players.','live',102773,NULL),
  ('bolton-how-to-play','audit-faction-bolton','Boltons punish the enemy by inflicting BLEED. They thrive against fast-paced teams and those who rely on Buffs.','live',102776,NULL)
